import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

src_cpp = r'''
#include <torch/extension.h>
#include <ATen/ATen.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void hinge_loss_kernel(const half* __restrict__ pred,
                                  const half* __restrict__ target,
                                  float* __restrict__ sum,
                                  int batch,
                                  int dim) {
    int total = batch * dim;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    float local = 0.0f;
    for (int i = idx; i < total; i += stride) {
        int row = i / dim;
        half p = pred[i];
        half t = target[row];
        float prod = __half2float(p) * __half2float(t);
        float val = 1.0f - prod;
        if (val > 0.0f) {
            local += val;
        }
    }
    atomicAdd(sum, local);
}

__global__ void mean_kernel(const float* __restrict__ sum,
                            half* __restrict__ out,
                            int total) {
    if (threadIdx.x == 0 && blockIdx.x == 0) {
        float mean = sum[0] / static_cast<float>(total);
        out[0] = __float2half(mean);
    }
}

torch::Tensor hinge_loss_forward(torch::Tensor pred, torch::Tensor target) {
    TORCH_CHECK(pred.dtype() == torch::kFloat16, "pred must be float16");
    TORCH_CHECK(target.dtype() == torch::kFloat16, "target must be float16");
    TORCH_CHECK(pred.is_cuda() && target.is_cuda(), "inputs must be CUDA tensors");
    TORCH_CHECK(pred.dim() == 2, "pred must be 2-D (batch, dim)");
    TORCH_CHECK(target.dim() == 1, "target must be 1-D (batch)");

    auto out = torch::empty({}, pred.options());
    auto sum = torch::zeros({1}, pred.options().dtype(torch::kFloat32));

    int batch = pred.size(0);
    int dim   = pred.size(1);
    int total = batch * dim;

    const int threads = 256;
    const int blocks = (total + threads - 1) / threads;

    hinge_loss_kernel<<<blocks, threads>>>(
        reinterpret_cast<const half*>(pred.data_ptr<at::Half>()),
        reinterpret_cast<const half*>(target.data_ptr<at::Half>()),
        sum.data_ptr<float>(),
        batch,
        dim
    );
    mean_kernel<<<1, 1>>>(
        sum.data_ptr<float>(),
        reinterpret_cast<half*>(out.data_ptr<at::Half>()),
        total
    );

    return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("hinge_loss_forward", &hinge_loss_forward, "Hinge loss forward (CUDA)");
}
'''

module = load_inline(name="hinge_loss_cuda",
                     cpp_sources=[src_cpp],
                     functions=["hinge_loss_forward"],
                     verbose=False)

